  `checkin_close_minutes` int NOT NULL DEFAULT 30 COMMENT '值机关闭：起飞前多少分钟',
  `iata_delay_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'IATA延误原因代码',
  `compensation_rule` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '补偿规则JSON',
  `stops` int NOT NULL DEFAULT 0,
  `punctuality` int NULL DEFAULT NULL,
  `meal_provided` tinyint NOT NULL DEFAULT 1,
  `wifi` tinyint NOT NULL DEFAULT 0,
  `power` tinyint NOT NULL DEFAULT 0,
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `actual_departure_time` datetime NULL DEFAULT NULL COMMENT '实际起飞时间',
  `actual_arrival_time` datetime NULL DEFAULT NULL COMMENT '实际到达时间',
  `version` int NOT NULL DEFAULT 0,
  `deleted` tinyint NOT NULL DEFAULT 0,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_flight_no`(`flight_no` ASC) USING BTREE,
  INDEX `idx_flight_date`(`flight_date` ASC) USING BTREE,
  INDEX `idx_route_date`(`departure_airport` ASC, `arrival_airport` ASC, `flight_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '航班表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of flight
-- ----------------------------

-- ----------------------------
-- Table structure for flight_cabin
-- ----------------------------
DROP TABLE IF EXISTS `flight_cabin`;
CREATE TABLE `flight_cabin`  (
  `id` bigint NOT NULL,
  `flight_id` bigint NOT NULL,
  `cabin_class` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cabin_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `fare` decimal(10, 2) NOT NULL,
  `tax` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `total_price` decimal(10, 2) NOT NULL,
  `total_seats` int NOT NULL,
  `available_seats` int NOT NULL,
  `baggage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `refund_rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `change_rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `advance_purchase_days` int NULL DEFAULT NULL COMMENT '需提前购买天数',
  `blackout_start` date NULL DEFAULT NULL COMMENT '黑屏期开始',
  `blackout_end` date NULL DEFAULT NULL COMMENT '黑屏期结束',
  `corporate_fare` decimal(10, 2) NULL DEFAULT NULL COMMENT '大客户协议运价',
  `version` int NOT NULL DEFAULT 0,
  `deleted` tinyint NOT NULL DEFAULT 0,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_flight_cabin`(`flight_id` ASC, `cabin_class` ASC) USING BTREE,
  INDEX `idx_flight_id`(`flight_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '航班舱位表' ROW_FORMAT = Dynamic;

