-- ----------------------------
-- Table structure for ground_handling
-- ----------------------------
DROP TABLE IF EXISTS `ground_handling`;
CREATE TABLE `ground_handling`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `flight_id` bigint NOT NULL COMMENT '航班ID',
  `node_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '保障节点编码',
  `node_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '保障环节名称',
  `plan_time` datetime NOT NULL COMMENT '计划时间',
  `actual_time` datetime NULL DEFAULT NULL COMMENT '实际时间',
  `delay_minutes` int NULL DEFAULT NULL COMMENT '延误分钟数',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/IN_PROGRESS/COMPLETED/FAILED',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_flight_node`(`flight_id` ASC, `node_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '地面保障节点表' ROW_FORMAT = Dynamic;

