-- Records of ground_handling
-- ----------------------------

-- ----------------------------
-- Table structure for irregular_operation
-- ----------------------------
DROP TABLE IF EXISTS `irregular_operation`;
CREATE TABLE `irregular_operation`  (
  `id` bigint NOT NULL COMMENT '主键（雪花ID）',
  `flight_id` bigint NOT NULL COMMENT '航班ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'DELAY/CANCEL/DIVERT/RETURN',
  `iata_delay_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'IATA延误原因代码',
  `reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '具体原因',
  `delay_minutes` int NULL DEFAULT NULL COMMENT '延误分钟数',
  `compensation_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '补偿类型 NONE/MEAL/HOTEL/CASH/VOUCHER',
  `compensation_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '补偿金额',
  `auto_rebooked` tinyint NOT NULL DEFAULT 0 COMMENT '是否自动改签',
  `notify_passengers` tinyint NOT NULL DEFAULT 0 COMMENT '是否已通知旅客',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PROCESSED' COMMENT 'PROCESSED/PENDING_REVIEW',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_flight_id`(`flight_id` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '不正常航班操作记录' ROW_FORMAT = Dynamic;

