INSERT INTO `feedback` VALUES (1, 1004, 'COMPLAINT', 1005, '航班取消后退款迟迟未到账，已等待超过5个工作日，请尽快处理。', '13800138004', NULL, 'PENDING', NULL, '2026-06-25 14:00:00', '2026-06-25 19:06:50');
INSERT INTO `feedback` VALUES (2, 1002, 'SUGGESTION', NULL, '建议增加航班延误险的自动理赔功能，减少人工申请流程。', '13800138002', NULL, 'PENDING', NULL, '2026-06-25 10:00:00', '2026-06-25 19:06:50');
